// Factory method for creating JSGeneratorObject:
DirectHandle<JSGeneratorObject> Factory::NewJSGeneratorObject(
    DirectHandle<JSFunction> function) {
  DCHECK(IsResumableFunction(function->shared()->kind()));
  JSFunction::EnsureHasInitialMap(isolate(), function);
  DirectHandle<Map> map(function->initial_map(), isolate());

  DCHECK(map->instance_type() == JS_GENERATOR_OBJECT_TYPE ||
         map->instance_type() == JS_ASYNC_GENERATOR_OBJECT_TYPE);

  return Cast<JSGeneratorObject>(NewJSObjectFromMap(map));
}

// Key creation steps:
// 1. Check function is resumable (generator or async generator)
// 2. Ensure function has initial map
// 3. Get the map from function->initial_map()
// 4. Create object using NewJSObjectFromMap(map)
// 5. Cast to JSGeneratorObject

